/// The string id (`ProxyIdentifier.sid`) of a proxy id, in either direction.
pub fn name_of(id: u8) -> Option<&'static str> {
    main::ALL.iter().chain(ext_host::ALL.iter()).find(|(_, i)| *i == id).map(|(n, _)| *n)
}

/// The id of a string id (`ProxyIdentifier.sid`).
pub fn id_of(name: &str) -> Option<u8> {
    main::ALL.iter().chain(ext_host::ALL.iter()).find(|(n, _)| *n == name).map(|(_, i)| *i)
}

/// True when `id` is a `MainContext` shape (a request the extension host sends us).
pub fn is_main(id: u8) -> bool {
    (1..=main::ALL.len() as u8).contains(&id)
}
